import re
from fractions import Fraction

_UNITS = ["KiB", "MiB", "GiB", "TiB"]  # index k-1 holds 1024**k

_SIZE_RE = re.compile(r"(-?[0-9]+(?:\.[0-9]+)?) *(B|KiB|MiB|GiB|TiB)")

_UNIT_POWER = {"B": 0, "KiB": 1, "MiB": 2, "GiB": 3, "TiB": 4}


def _tenths(a, k):
    """a / 1024**k rounded to one decimal, exact half away from zero (a >= 0).

    Returns the value times 10 as an int.
    """
    n = a * 10
    d = 1024 ** k
    return (2 * n + d) // (2 * d)


def format_size(count):
    """A byte count as text with a binary unit. See TASK.md."""
    if isinstance(count, bool) or not isinstance(count, int):
        raise TypeError("count must be an int, not %s" % type(count).__name__)

    sign = "-" if count < 0 else ""
    a = abs(count)

    if a < 1024:
        return "%s%d B" % (sign, a)

    # Largest unit k (1..4) in which the value is at least 1.
    k = 1
    for candidate in (4, 3, 2, 1):
        if a >= 1024 ** candidate:
            k = candidate
            break

    t = _tenths(a, k)
    # Rounding up to 1024.0 moves to the next unit (TiB is the last).
    if t >= 10240 and k < 4:
        k += 1
        t = _tenths(a, k)

    return "%s%d.%d %s" % (sign, t // 10, t % 10, _UNITS[k - 1])


def parse_size(text):
    """The byte count that a size text stands for. See TASK.md."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, not %s" % type(text).__name__)

    m = _SIZE_RE.fullmatch(text.strip(" "))
    if m is None:
        raise ValueError("not a size: %r" % text)

    number, unit = m.group(1), m.group(2)
    if unit == "B" and "." in number:
        raise ValueError("a fraction is not allowed with B: %r" % text)

    value = Fraction(number) * (1024 ** _UNIT_POWER[unit])
    if value.denominator != 1:
        raise ValueError("not a whole number of bytes: %r" % text)
    return int(value)
